function parseNums(s){
  var parts=String(s||'').trim().split(/[,\s]+/).filter(function(x){return x.length;});
  if(!parts.length) return { value:null, error:'\u6837\u672c\u4e3a\u7a7a' };
  var out=[];
  for(var i=0;i<parts.length;i++){
    var n=Number(parts[i]);
    if(!isFinite(n)) return { value:null, error:'\u975e\u6cd5\u6570\u5b57: '+parts[i] };
    out.push(n);
  }
  return { value:out, error:null };
}
function percentile(arr, p){
  if(!arr.length) throw new Error('EMPTY');
  if(p<0||p>100) throw new Error('P_RANGE');
  var a=arr.slice().sort(function(x,y){return x-y;});
  if(a.length===1) return a[0];
  var idx=(p/100)*(a.length-1);
  var lo=Math.floor(idx), hi=Math.ceil(idx);
  if(lo===hi) return a[lo];
  return a[lo]+(a[hi]-a[lo])*(idx-lo);
}
function mean(arr){
  if(!arr.length) throw new Error('EMPTY');
  return arr.reduce(function(a,b){return a+b;},0)/arr.length;
}
function stddev(arr){
  if(arr.length<2) return 0;
  var m=mean(arr);
  return Math.sqrt(arr.reduce(function(s,x){return s+(x-m)*(x-m);},0)/(arr.length-1));
}
function summary(arr){
  return { count:arr.length, min:Math.min.apply(null,arr), max:Math.max.apply(null,arr),
    mean:mean(arr), stddev:stddev(arr),
    p50:percentile(arr,50), p90:percentile(arr,90), p95:percentile(arr,95), p99:percentile(arr,99) };
}
function histogram(arr, buckets){
  buckets=buckets||8;
  var mn=Math.min.apply(null,arr), mx=Math.max.apply(null,arr);
  var w=(mx-mn)/buckets || 1;
  var out=[];
  for(var i=0;i<buckets;i++) out.push({ from:mn+i*w, to:mn+(i+1)*w, count:0 });
  arr.forEach(function(x){
    var i=Math.min(buckets-1, Math.floor((x-mn)/w));
    out[i].count++;
  });
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseNums:parseNums, percentile:percentile, mean:mean, stddev:stddev,
    summary:summary, histogram:histogram };
}
if (typeof window !== 'undefined') {
  window.PercentileForgePure = { parseNums:parseNums, percentile:percentile, mean:mean, stddev:stddev,
    summary:summary, histogram:histogram };
}
